bash -lc python - <<'PY'
import requests
u='https://www.financialexpress.com/trending/openai-whistleblower-suchir-balajis-mother-shares-video-of-poor-evidence-handling-were-they-paid-or/3808192/'
try:
 r=requests.get(u,timeout=15,headers={'User-Agent':'Mozilla/5.0'}); print(r.status_code, len(r.content));
 s=r.text; import re
 for x in re.findall(r'https?[^\s"\']*RaoPoornima[^\s"\']*',s)[:8]:print(x[:250])
 for m in re.finditer('xuW4HUwRqV',s):print(s[max(0,m.start()-900):m.start()+800][:1700])
except Exception as e:print(type(e),str(e)[:500])
PY

bash -lc python - <<'PY'
import requests
url='https://data.sf.gov/resource/nuek-vuh3.json'
p={'$where':"call_date between '2024-11-25T00:00:00' and '2024-11-27T23:59:59' AND upper(address) like '%BUCHANAN%'",'$limit':1000}
try:
 r=requests.get(url,params=p,timeout=12);print(r.status_code,r.url);print(r.text[:4000])
except Exception as e: print(type(e).__name__,str(e))
PY

